def test_nested_blueprint_registration_names(app):
    from werkzeug.test import Client

    client = Client(app, app.response_class)
    parent = flask.Blueprint("parent", __name__)
    child = flask.Blueprint("child", __name__)
    grandchild = flask.Blueprint("grandchild", __name__)
    calls = []

    @child.before_request
    def before():
        calls.append(("before", flask.request.blueprint))

    @child.after_request
    def after(response):
        response.headers["X-Child"] = flask.request.blueprint
        return response

    @child.teardown_request
    def teardown(error):
        calls.append(("teardown", flask.request.blueprint))

    @child.context_processor
    def context():
        return {"mount": flask.request.blueprint}

    @child.url_value_preprocessor
    def values(endpoint, values):
        flask.g.value = values.pop("value")

    @grandchild.url_defaults
    def defaults(endpoint, values):
        values.setdefault("value", flask.g.value)

    @grandchild.route("/")
    def index():
        return flask.render_template_string(
            "{{ mount }} {{ url_for('.index') }}"
        )

    @grandchild.route("/no")
    def no():
        flask.abort(403)

    @child.errorhandler(403)
    def forbidden(error):
        return flask.url_for(".index"), 403

    child.register_blueprint(grandchild, name="leaf", url_prefix="/leaf")
    parent.register_blueprint(child, name="branch", url_prefix="/<value>")
    app.register_blueprint(parent, name="one", url_prefix="/one")
    app.register_blueprint(parent, name="two", url_prefix="/two")

    assert app.blueprints == {
        "one": parent,
        "one.branch": child,
        "one.branch.leaf": grandchild,
        "two": parent,
        "two.branch": child,
        "two.branch.leaf": grandchild,
    }

    for mount in ("one", "two"):
        name = f"{mount}.branch.leaf"
        path = f"/{mount}/example/leaf/"
        response = client.get(path)
        assert response.get_data(as_text=True) == f"{name} {path}"
        assert response.headers["X-Child"] == name
        response = client.get(path + "no")
        assert response.status_code == 403
        assert response.get_data(as_text=True) == path
        assert calls == [("before", name), ("teardown", name)] * 2
        calls.clear()


def test_nested_blueprint_same_child_names(app):
    first = flask.Blueprint("first", __name__)
    second = flask.Blueprint("second", __name__)
    first_child = flask.Blueprint("child", __name__)
    second_child = flask.Blueprint("child", __name__)
    first.register_blueprint(first_child)
    second.register_blueprint(second_child)
    app.register_blueprint(first)
    app.register_blueprint(second)

    assert app.blueprints["first.child"] is first_child
    assert app.blueprints["second.child"] is second_child


